describe('Visit encounter start', () => {
  it('records when the encounter started for a checked-in visitor, only once', () => {
    const visit = expected();
    visit.checkIn(new Date('2026-03-02T09:50:00Z'));

    visit.markEncounterStarted(new Date('2026-03-02T10:05:00Z'));
    visit.markEncounterStarted(new Date('2026-03-02T11:00:00Z'));

    expect(visit.encounterStartedAt).toEqual(new Date('2026-03-02T10:05:00Z'));
  });

  it('ignores an encounter start for a visitor who never checked in', () => {
    const visit = expected();

    visit.markEncounterStarted(new Date('2026-03-02T10:05:00Z'));

    expect(visit.encounterStartedAt).toBeNull();
  });
});

describe('WaitingTimeMetrics', () => {
  function attended(id: string, checkedIn: string, started?: string): Visit {
    const visit = expected(id);
    visit.checkIn(new Date(checkedIn));
    if (started) {
      visit.markEncounterStarted(new Date(started));
    }
    return visit;
  }

  it('computes average and maximum wait between check-in and encounter start', () => {
    const metrics = WaitingTimeMetrics.of([
      attended('a', '2026-03-02T09:00:00Z', '2026-03-02T09:10:00Z'),
      attended('b', '2026-03-02T09:00:00Z', '2026-03-02T09:30:00Z'),
    ]);

    expect(metrics.sampleSize).toBe(2);
    expect(metrics.averageSeconds).toBe(20 * 60);
    expect(metrics.maximumSeconds).toBe(30 * 60);
  });

  it('ignores visitors still waiting', () => {
    const metrics = WaitingTimeMetrics.of([
      attended('a', '2026-03-02T09:00:00Z', '2026-03-02T09:10:00Z'),
      attended('b', '2026-03-02T09:05:00Z'),
      expected('c'),
    ]);

    expect(metrics.sampleSize).toBe(1);
    expect(metrics.maximumSeconds).toBe(10 * 60);
  });

  it('has no average or maximum when nobody has been attended', () => {
    const metrics = WaitingTimeMetrics.of([]);

    expect(metrics.sampleSize).toBe(0);
    expect(metrics.averageSeconds).toBeNull();
    expect(metrics.maximumSeconds).toBeNull();
  });
});
